    # Bounded gradient polish of the incumbent: annealed soft-min L-BFGS-B
    # (exact analytic gradient) followed by an exact active-set SLSQP pass
    # that drives the binding min-area constraints to a KKT point.
    def _polish(x0, bv, b):
        x = _normalize(x0.reshape(_N, 2)).ravel()
        for T in (3e-3, 1e-3, 3e-4, 1e-4):
            try:
                res = minimize(lambda z: (-_softmin_val_grad(z, tri, T)[0],
                                          -_softmin_val_grad(z, tri, T)[1]),
                               x, method='L-BFGS-B', jac=True,
                               options={'maxiter': 300, 'ftol': 1e-14})
                if np.all(np.isfinite(res.x)):
                    x = res.x
            except Exception:
                pass
        pts = _normalize(x.reshape(_N, 2))
        v = _valid_candidate(pts.copy(), floor=0.0)
        if v > bv:
            bv, b = v, pts.copy()
        # Active-set SLSQP: require all active triangles >= current min.
        try:
            ar = _areas(pts, tri)
            tmin = ar.min()
            act = np.where(ar <= tmin * (1.0 + 0.05) + 1e-12)[0]
            act_tri = tri[act]

            def cons(z):
                return _areas(z.reshape(_N, 2), act_tri) - tmin * 0.999

            def cons_jac(z):
                g = _area_grad(z.reshape(_N, 2), act_tri)
                return g.reshape(act_tri.shape[0], -1)

            res = minimize(lambda z: 0.0, pts.ravel(), method='SLSQP',
                           jac=lambda z: np.zeros(2 * _N),
                           constraints=[{'type': 'ineq', 'fun': cons,
                                         'jac': cons_jac}],
                           options={'maxiter': 150, 'ftol': 1e-12})
            if np.all(np.isfinite(res.x)):
                p2 = _normalize(res.x.reshape(_N, 2))
                v2 = _valid_candidate(p2.copy(), floor=0.0)
                if v2 > bv:
                    bv, b = v2, p2.copy()
        except Exception:
            pass
        return bv, b

